const isLivingIn = ([x, y]: Cell, livingCells: Cell[]): boolean =>
  livingCells.some(([lx, ly]) => lx === x && ly === y);

const neighboursOf = ([x, y]: Cell): Cell[] => {
  const cells: Cell[] = [];
  for (let dx = -1; dx <= 1; dx++) {
    for (let dy = -1; dy <= 1; dy++) {
      if (dx !== 0 || dy !== 0) cells.push([x + dx, y + dy]);
    }
  }
  return cells;
};

export function nextGeneration(livingCells: Cell[]): Cell[] {
  const survivors = livingCells.filter((cell) => {
    const neighbours = countLivingNeighbours(cell, livingCells);
    return neighbours === 2 || neighbours === 3;
  });

  const births: Cell[] = [];
  for (const living of livingCells) {
    for (const candidate of neighboursOf(living)) {
      if (isLivingIn(candidate, livingCells)) continue;
      if (isLivingIn(candidate, births)) continue;
      if (countLivingNeighbours(candidate, livingCells) === 3) {
        births.push(candidate);
      }
    }
  }

  return [...survivors, ...births];
}

