  Math.abs(otherY - y) <= 1;

const countLivingNeighbours = (cell: Cell, livingCells: Cell[]): number =>
  livingCells.filter((other) => isNeighbourOf(cell, other)).length;

export function nextGeneration(livingCells: Cell[]): Cell[] {
  return livingCells.filter((cell) => {
    const neighbours = countLivingNeighbours(cell, livingCells);
    return neighbours === 2 || neighbours === 3;
  });
}

